<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ApiError, api } from '../api/client'
import type { ArtifactDetail, CheckStatus, RunDetail, RunExecutionState, RunPlan, RunSummary } from '../api/contracts'
import StatusBadge from '../components/StatusBadge.vue'
const route = useRoute(), runs = ref<RunSummary[]>([]), detail = ref<RunDetail | null>(null), frozenPlan = ref<RunPlan | null>(null), artifact = ref<ArtifactDetail | null>(null), execution = ref<RunExecutionState | null>(null), filter = ref<string>(''), error = ref(''), artifactError = ref(''), loading = ref(true), detailLoading = ref(false), retrying = ref(false), retryConfirm = ref(false), openingArtifact = ref(false), polling = ref(false), progressMessage = ref('')
const states: Array<CheckStatus | ''> = ['', 'passed', 'failed', 'unavailable', 'indeterminate', 'skipped']
const stageLabels: Record<string, string> = { source: 'Source / 读取需求', compiler: 'Compiler / 生成 Spec', maker: 'Maker / 生成代码', checker: 'Checkers / 验收', delivery: 'Delivery / 交付' }
const latestEvent = computed(() => detail.value?.events[detail.value.events.length - 1])
const deliveryRetryAllowed = computed(() => latestEvent.value?.stage === 'delivery' && latestEvent.value.status === 'failed')
const planSteps = computed(() => frozenPlan.value ? [{ id: 'source', label: `${stageLabels.source} · ${frozenPlan.value.components.source}` }, { id: 'compiler', label: `${stageLabels.compiler} · ${frozenPlan.value.components.compiler}` }, { id: 'maker', label: `${stageLabels.maker} · ${frozenPlan.value.components.maker}` }, { id: 'checker', label: `${stageLabels.checker} · ${frozenPlan.value.components.checkers.join(' + ')}` }, { id: 'delivery', label: `${stageLabels.delivery} · ${frozenPlan.value.components.delivery}` }] : [])
const deliveryConfig = computed(() => frozenPlan.value?.profile.delivery_config || {})
const isGithubWorkflow = computed(() => frozenPlan.value?.components.delivery === 'github_workflow')
function githubUrl(repo: unknown) { const match = typeof repo === 'string' ? repo.match(/^github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+?)(?:\.git)?$/) : null; return match ? `https://github.com/${match[1]}/${match[2]}` : null }
const githubTargetUrl = computed(() => githubUrl(deliveryConfig.value.repo))
const assetUrl = (url: string) => import.meta.env.DEV ? `/studio-api${url}` : url
let timer: ReturnType<typeof setTimeout> | undefined, generation = 0
function stopPolling() { if (timer) clearTimeout(timer); timer = undefined; polling.value = false }
function terminal() { const event = latestEvent.value; return Boolean(event && (event.stage === 'delivery' || event.status !== 'passed')) || Boolean(!detail.value && execution.value && !['planned', 'queued', 'running'].includes(execution.value.state)) }
function stepState(stage: string) { const events = detail.value?.events.filter(item => item.stage === stage) || [], event = events[events.length - 1]; if (event) return event.status; const last = latestEvent.value; const order = ['source', 'compiler', 'maker', 'checker', 'delivery']; return !last || order.indexOf(stage) === order.indexOf(last.stage) + 1 ? 'waiting' : 'pending' }
function updateProgress() { const event = latestEvent.value; if (!detail.value) { const state = execution.value?.state || 'queued'; if (state === 'failed') { progressMessage.value = execution.value?.reason || '执行器在写入第一条阶段证据前异常终止。'; return }; progressMessage.value = state === 'running' ? '执行器正在启动，等待 Source 阶段的第一条证据…' : '已创建受控 Run，正在排队等待执行器启动…'; return } if (terminal()) { progressMessage.value = event?.status === 'passed' ? '全部阶段已记录完成。' : `${stageLabels[event?.stage || ''] || event?.stage} 已记录为 ${event?.status}，后续阶段不会被推断为完成。`; return } const order = ['source', 'compiler', 'maker', 'checker', 'delivery'], next = order[order.indexOf(event?.stage || '') + 1]; progressMessage.value = `已记录 ${stageLabels[event?.stage || ''] || event?.stage} 的通过证据；正在等待 ${stageLabels[next] || next} 的完成证据。` }
async function loadRuns(silent = false) { if (!silent) loading.value = true; try { runs.value = (await api.runs(filter.value || undefined)).runs } catch (e) { error.value = e instanceof Error ? e.message : '无法读取运行投影' } finally { if (!silent) loading.value = false } }
async function open(runId: string, follow = false) { stopPolling(); const token = ++generation; retryConfirm.value = false; artifact.value = null; execution.value = null; artifactError.value = ''; error.value = ''; progressMessage.value = ''; try { frozenPlan.value = (await api.runPlan(runId)).plan } catch { frozenPlan.value = null } const refresh = async () => { if (token !== generation) return; const submittedError = sessionStorage.getItem(`loop-run-submit-error:${runId}`); if (submittedError) { sessionStorage.removeItem(`loop-run-submit-error:${runId}`); error.value = submittedError; progressMessage.value = '执行请求未启动；没有 RunEvent 被写入。'; stopPolling(); return } detailLoading.value = true; try { detail.value = (await api.run(runId)).run; artifact.value = (await api.artifact(runId)).artifact; execution.value = null } catch (e) { detail.value = null; artifact.value = null; if (follow && e instanceof ApiError && e.status === 404) { try { execution.value = await api.runState(runId) } catch { execution.value = null } } else if (!follow) error.value = e instanceof Error ? e.message : '无法读取 Run 详情' } finally { detailLoading.value = false } updateProgress(); const keepPolling = (follow || Boolean(detail.value)) && !terminal(); polling.value = keepPolling; if (keepPolling && token === generation) timer = setTimeout(refresh, 1500); else if (detail.value) void loadRuns(true) }; await refresh() }
async function openArtifactFolder() { if (!detail.value) return; openingArtifact.value = true; artifactError.value = ''; try { await api.openArtifactFolder(detail.value.run_id) } catch (e) { artifactError.value = e instanceof Error ? e.message : '无法打开本地目录' } finally { openingArtifact.value = false } }
async function retryDelivery() { if (!detail.value) return; retrying.value = true; error.value = ''; try { const result = await api.retryDelivery(detail.value.run_id); retryConfirm.value = false; if (result.run?.run_id) await open(result.run.run_id, true); if (!result.ok) error.value = result.run?.reason || result.error || 'Delivery 重试未通过，请查看新增的交付事件' } catch (e) { error.value = e instanceof Error ? e.message : 'Delivery 重试请求失败' } finally { retrying.value = false } }
watch(filter, () => loadRuns()); watch(() => ({ runId: route.params.runId, follow: route.query.follow }), value => { if (typeof value.runId === 'string') void open(value.runId, value.follow === '1'); else stopPolling() }, { immediate: true }); onMounted(() => loadRuns()); onBeforeUnmount(stopPolling)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">VERIFIED EVENT PROJECTION · LIVE REFRESH</p><h1>交付运行</h1><p>确认后立即进入此页。页面只轮询冻结 Plan 与已验证 RunEvent/Evidence：阶段完成、Checker 清单和生成文件会逐步出现，不以目录或时间猜测成功。</p></div><button class="quiet-button" @click="loadRuns()">刷新</button></div><p v-if="error" class="data-warning">⚠ {{ error }}；未回退到兼容数据。</p><div class="filter-row"><button v-for="state in states" :key="state || 'all'" :class="{ active: filter === state }" @click="filter = state">{{ state || '全部' }}</button></div><div class="runs-layout"><section class="run-cards"><p v-if="loading" class="empty-state">正在读取权威事件投影…</p><p v-else-if="!runs.length" class="empty-state">没有匹配的 Run；缺少记录不能被解释为通过。</p><button v-for="run in runs" :key="run.run_id" class="run-card" @click="$router.push(`/runs/${encodeURIComponent(run.run_id)}`)"><StatusBadge :status="run.status"/><h3>{{ run.task?.title || run.run_id }}</h3><p>{{ run.task ? `${run.task.id} · ${run.run_id}` : run.run_id }}</p><div><StatusBadge :status="run.integrity"/><span>{{ run.event_count }} events</span><b>查看详情 →</b></div></button></section><aside class="run-detail"><p class="eyebrow">{{ detail?.run_id || frozenPlan?.run_id || 'RUN DETAIL' }}</p><section v-if="frozenPlan" class="run-progress"><div><b>实时状态</b><span>{{ polling ? '每 1.5 秒刷新' : '已停止刷新' }}</span></div><p>{{ progressMessage || '正在读取 Run 事件…' }}</p><ol><li v-for="step in planSteps" :key="step.id" :class="stepState(step.id)"><b>{{ step.label }}</b><span>{{ stepState(step.id) === 'waiting' ? '等待证据' : stepState(step.id) === 'pending' ? '未开始' : stepState(step.id) }}</span></li></ol></section><template v-if="detail"><h2>{{ detail.task?.title || detail.run_id }}</h2><p v-if="detail.task" class="task-meta">{{ detail.task.id }} · P{{ detail.task.priority }} · {{ detail.task.profile_id }}</p><div class="detail-actions"><RouterLink v-if="detail.task" class="quiet-button" :to="`/requirements/${detail.task.id}`">查看需求</RouterLink></div><section class="artifact-panel"><h3>生成代码</h3><p v-if="artifactError" class="data-warning">⚠ {{ artifactError }}</p><p v-else-if="!artifact" class="empty-state">尚未记录制品；Maker 完成后会自动刷新文件清单。</p><template v-else-if="artifact.available"><p class="artifact-path"><b>代码路径</b><code>{{ artifact.relative_path }}</code></p><p class="artifact-meta">已生成 {{ artifact.file_count }} 个文件；清单会随下一次事件刷新。</p><div class="detail-actions"><a v-if="artifact.preview_url" class="primary-button" :href="assetUrl(artifact.preview_url)" target="_blank" rel="noopener">打开本地预览</a><button v-if="artifact.open_local_supported" class="quiet-button" :disabled="openingArtifact" @click="openArtifactFolder">{{ openingArtifact ? '正在打开…' : '在 Finder 中打开' }}</button></div><ul class="artifact-files"><li v-for="file in artifact.files" :key="file.path"><a :href="assetUrl(file.url)" target="_blank" rel="noopener">{{ file.path }}</a><small>{{ file.bytes }} B</small></li></ul><p v-if="artifact.truncated" class="empty-state">文件过多，仅展示前 500 个。</p></template><p v-else class="empty-state">Maker 尚未产出可展示的本地制品。</p></section><section v-if="frozenPlan" class="artifact-panel"><h3>发布与部署</h3><p class="artifact-path"><b>交付方式</b><code>{{ frozenPlan.components.delivery }}</code></p><template v-if="isGithubWorkflow"><p class="artifact-path"><b>GitHub 目标仓库（冻结计划）</b><a v-if="githubTargetUrl" :href="githubTargetUrl" target="_blank" rel="noopener">{{ deliveryConfig.repo }}</a><code v-else>{{ deliveryConfig.repo || '未配置' }}</code></p><p v-if="deliveryConfig.branch" class="artifact-path"><b>目标分支（冻结计划）</b><code>{{ deliveryConfig.branch }}</code></p><p v-if="detail.delivery?.location_url" class="artifact-path"><b>GitHub 发布目录（已验证结果）</b><a :href="detail.delivery.location_url" target="_blank" rel="noopener">打开已发布代码</a></p><p v-else class="artifact-meta">GitHub 发布目录：暂无可展示的已验证地址。</p><p v-if="detail.delivery?.commit_url" class="artifact-path"><b>发布 Commit（已验证结果）</b><a :href="detail.delivery.commit_url" target="_blank" rel="noopener">{{ detail.delivery.commit_sha }}</a></p><p v-if="detail.delivery?.workflow_status" class="artifact-meta">GitHub Workflow：{{ detail.delivery.workflow_status }}</p><p class="artifact-path"><b>ECS 访问地址</b><a v-if="detail.delivery?.deployment_url" :href="detail.delivery.deployment_url" target="_blank" rel="noopener">{{ detail.delivery.deployment_url }}</a><span v-else>未收到可验证的部署地址；GitHub 发布成功不会被推断为 ECS 已可访问。</span></p><p v-if="detail.delivery?.ecs_health" class="artifact-meta">ECS 健康状态：{{ detail.delivery.ecs_health }}</p></template><p v-else class="artifact-meta">此 Profile 未配置 GitHub Workflow / ECS 交付；仅展示本地制品。</p></section><h3><StatusBadge :status="detail.status"/> <StatusBadge :status="detail.integrity"/></h3></template><p v-else class="empty-state">选择一个 Run 查看关联需求、阶段、Checker、生成代码与 evidence。</p><p v-if="detailLoading" class="empty-state">正在读取最新阶段证据…</p><div v-if="detail" class="timeline"><div v-for="event in detail.events" :key="event.event_id"><i></i><b>{{ event.sequence }}. {{ stageLabels[event.stage] || event.stage }} <StatusBadge :status="event.status"/></b><small>{{ event.occurred_at }} · attempt {{ event.attempt }} · evidence {{ event.evidence_integrity }}</small><small v-if="event.evidence.length">{{ event.evidence.map(item => item.digest.slice(0, 16) + '…').join(', ') }}</small></div></div><div v-if="deliveryRetryAllowed" class="retry-delivery"><button v-if="!retryConfirm" class="quiet-button" @click="retryConfirm = true">重试失败的 Delivery</button><div v-else class="confirm-box"><b>只重试冻结制品的 GitHub Delivery，不会重新调用模型或 Checker；这会再次尝试推送，并触发目标仓 Workflow 的 ECS 部署。</b><button class="primary-button" :disabled="retrying" @click="retryDelivery">{{ retrying ? '正在重试 Delivery…' : '确认重试 Delivery' }}</button></div></div></aside></div></section></template>
<style scoped>.task-meta{color:var(--muted);font-size:12px}.detail-actions{display:flex;gap:8px;margin:14px 0}.run-progress,.artifact-panel{margin:16px 0;padding:14px;border:1px solid var(--line);border-radius:10px;background:var(--panel-2)}.run-progress>div{display:flex;justify-content:space-between;gap:12px}.run-progress>div span,.run-progress p{color:var(--muted);font-size:12px}.run-progress ol{display:grid;gap:7px;margin:12px 0 0;padding:0;list-style:none}.run-progress li{display:flex;justify-content:space-between;gap:10px;padding:8px;border-left:3px solid var(--line);background:var(--panel)}.run-progress li span{font-size:11px}.run-progress li.passed{border-color:var(--mint)}.run-progress li.failed,.run-progress li.unavailable,.run-progress li.indeterminate{border-color:var(--red)}.run-progress li.waiting{border-color:var(--amber)}.run-progress li.pending{opacity:.62}.artifact-panel h3{margin:0 0 10px}.artifact-path{display:grid;gap:5px;margin:0}.artifact-path b{font-size:11px;color:var(--muted)}.artifact-path code{overflow-wrap:anywhere}.artifact-meta{font-size:12px;color:var(--muted)}.artifact-files{max-height:220px;overflow:auto;margin:10px 0 0;padding:0;list-style:none;border-top:1px solid var(--line)}.artifact-files li{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid var(--line);font-size:12px}.artifact-files a{overflow-wrap:anywhere}.artifact-files small{white-space:nowrap;color:var(--muted)}.retry-delivery{margin-top:16px}.confirm-box{display:grid;gap:10px;padding:13px;border:1px solid color-mix(in srgb,var(--amber) 45%,var(--line));border-radius:10px;color:var(--amber);font-size:12px}.confirm-box button{justify-self:start}@media(max-width:620px){.run-progress li,.run-progress>div{align-items:flex-start;flex-direction:column}}</style>
